<template>
	<view class="expand-page">
		<view class="fixed-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="nav-bar">
				<view class="nav-side">
					<view class="nav-action" @click="goBack">
						<image class="back-icon" src="/static/fanhui.png" mode="aspectFit" />
					</view>
				</view>
				<view class="nav-title">我要扩写</view>
				<view class="nav-side is-right"></view>
			</view>
		</view>

		<scroll-view class="expand-body" scroll-y enhanced :show-scrollbar="false" :style="{ paddingTop: headerTotalHeight + 'px' }">
			<view class="source-card">
				<view class="source-head">
					<text class="source-title">原始想法</text>
					<VipName class="source-meta" :name="source.displayName || '想法来客'" :is-member="source.authorIsMember" />
				</view>
				<text class="source-content">{{ source.content || '原文暂时不可见' }}</text>
			</view>

			<view class="style-card">
				<text class="section-title">选择扩写风格</text>
				<view class="style-select-wrap">
					<view class="style-select" @click="toggleStyleDropdown">
						<text class="style-select-text">{{ form.style }}</text>
						<text class="style-select-arrow">{{ showStyleDropdown ? '⌃' : '⌄' }}</text>
					</view>
					<view v-if="showStyleDropdown" class="style-dropdown">
						<view
							v-for="item in styleOptions"
							:key="item"
							class="style-option"
							:class="{ 'is-active': form.style === item }"
							@click="selectStyle(item)"
						>
							<text>{{ item }}</text>
						</view>
					</view>
				</view>
			</view>

			<view class="writer-card">
				<view class="writer-head">
					<text class="section-title">写成另一个版本</text>
					<text class="char-count">{{ form.content.length }} / 3000</text>
				</view>
				<textarea
					v-model="form.content"
					class="writer-area"
					placeholder="沿着这个念头，写出另一个宇宙里的版本"
					placeholder-class="writer-placeholder"
					maxlength="3000"
					auto-height
				/>
			</view>

			<view class="body-foot" />
		</scroll-view>

		<view class="fixed-footer">
			<view class="save-btn" :class="{ 'is-disabled': !canSubmit || submitting }" @click="submitExpansion">
				<text>{{ submitting ? '保存中...' : '保存扩写版本' }}</text>
			</view>
		</view>
	</view>
</template>

<script>
import { createThoughtExpansion, fetchThoughtDetail } from '../../api/thought';
import { showRequestError } from '../../utils/feedback';
import VipName from '../../components/VipName.vue';

export default {
	components: { VipName },
	data() {
		return {
			id: '',
			statusBarHeight: 44,
			headerTotalHeight: 88,
			submitting: false,
			showStyleDropdown: false,
			source: {},
			styleOptions: [
				'日记体',
				'小说片段',
				'电影独白',
				'梦境记录',
				'第二人生设定',
				'不会发生的结局',
				'更狠的版本',
				'更温柔的版本',
				'如果我真的越线了的虚构版本'
			],
			form: {
				style: '日记体',
				content: ''
			}
		};
	},
	computed: {
		canSubmit() {
			return Boolean(this.id && this.form.style && this.form.content.trim());
		}
	},
	onLoad(query) {
		this.setHeaderLayout();
		this.id = query.id || '';
		this.loadSource();
	},
	methods: {
		setHeaderLayout() {
			try {
				const systemInfo = uni.getSystemInfoSync();
				this.statusBarHeight = systemInfo.statusBarHeight || 44;
				const rpxToPx = (systemInfo.windowWidth || 375) / 750;
				const navBarPx = Math.round(88 * rpxToPx);
				this.headerTotalHeight = this.statusBarHeight + navBarPx;
			} catch (error) {
				this.statusBarHeight = 44;
				this.headerTotalHeight = 88;
			}
		},
		loadSource() {
			const source = uni.getStorageSync('thought_expansion_source') || {};
			if (source.sourceId === this.id) {
				this.source = source;
			}
			uni.removeStorageSync('thought_expansion_source');
			if (!this.source.content) {
				this.fetchSource();
			}
		},
		async fetchSource() {
			if (!this.id) return;
			try {
				const detail = (await fetchThoughtDetail(this.id)) || {};
				this.source = {
					sourceId: detail.id || this.id,
					content: detail.content || '',
					displayName: detail.displayName || detail.authorNickname || '',
					authorIsMember: Boolean(detail.authorIsMember)
				};
			} catch (error) {
				showRequestError(error, '原文加载失败');
			}
		},
		goBack() {
			uni.navigateBack();
		},
		selectStyle(style) {
			this.form.style = style;
			this.showStyleDropdown = false;
		},
		toggleStyleDropdown() {
			this.showStyleDropdown = !this.showStyleDropdown;
		},
		async submitExpansion() {
			if (this.submitting) return;
			if (!this.canSubmit) {
				uni.showToast({ title: '请选择风格并写下扩写内容', icon: 'none' });
				return;
			}

			this.submitting = true;
			try {
				await createThoughtExpansion(this.id, {
					style: this.form.style,
					content: this.form.content
				});
				uni.showToast({ title: '扩写已保存', icon: 'success', duration: 900 });
				setTimeout(() => {
					uni.navigateBack();
				}, 900);
			} catch (error) {
				showRequestError(error, '扩写保存失败');
			} finally {
				this.submitting = false;
			}
		}
	}
};
</script>

<style lang="scss" scoped>
.expand-page {
	min-height: 100vh;
	background: #f7f5f7;
}

.fixed-header {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	z-index: 20;
	background: rgba(255, 255, 255, 0.96);
	border-bottom: 1rpx solid #f1eef8;
	backdrop-filter: blur(14rpx);
}

.nav-bar {
	min-height: 88rpx;
	padding: 0 24rpx;
	display: flex;
	align-items: center;
	justify-content: space-between;
}

.nav-side {
	width: 96rpx;
	display: flex;
	align-items: center;
}

.nav-side.is-right {
	justify-content: flex-end;
}

.nav-action {
	width: 56rpx;
	height: 56rpx;
	display: flex;
	align-items: center;
	justify-content: center;
}

.back-icon {
	width: 34rpx;
	height: 34rpx;
	display: block;
}

.nav-title {
	font-size: 30rpx;
	font-weight: 600;
	color: #1a1a2e;
}

.expand-body {
	height: 100vh;
	box-sizing: border-box;
	padding-left: 24rpx;
	padding-right: 24rpx;
}

.source-card,
.style-card,
.writer-card {
	margin-top: 18rpx;
	padding: 28rpx 24rpx;
	border-radius: 20rpx;
	background: #ffffff;
	box-shadow: 0 2rpx 12rpx rgba(212, 104, 138, 0.06);
}

.style-card {
	position: relative;
	z-index: 5;
}

.source-head,
.writer-head {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 20rpx;
	margin-bottom: 18rpx;
}

.source-title,
.section-title {
	font-size: 28rpx;
	font-weight: 700;
	color: #1a1a2e;
}

.source-meta,
.char-count {
	flex-shrink: 0;
	font-size: 22rpx;
	color: #c0a2af;
}

.source-content {
	display: block;
	max-height: 220rpx;
	font-size: 26rpx;
	line-height: 1.72;
	color: #62565c;
	overflow: hidden;
}

.style-select-wrap {
	position: relative;
	margin-top: 22rpx;
}

.style-select {
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 76rpx;
	padding: 0 24rpx;
	border-radius: 18rpx;
	background: #fff7fa;
	border: 1rpx solid #efe1e7;
}

.style-select-text {
	font-size: 27rpx;
	font-weight: 600;
	color: #b56f88;
}

.style-select-arrow {
	font-size: 30rpx;
	color: #c99aac;
	line-height: 1;
}

.style-dropdown {
	position: absolute;
	top: 88rpx;
	left: 0;
	right: 0;
	z-index: 12;
	padding: 10rpx;
	border-radius: 18rpx;
	background: #ffffff;
	border: 1rpx solid #efe1e7;
	box-shadow: 0 18rpx 40rpx rgba(85, 55, 67, 0.12);
}

.style-option {
	display: flex;
	align-items: center;
	min-height: 66rpx;
	padding: 0 18rpx;
	border-radius: 14rpx;
	font-size: 26rpx;
	color: #6b5961;
}

.style-option + .style-option {
	margin-top: 4rpx;
}

.style-option.is-active {
	background: #fff3f7;
	color: #b56f88;
	font-weight: 700;
}

.writer-area {
	display: block;
	width: 100%;
	min-height: 420rpx;
	font-size: 28rpx;
	line-height: 1.8;
	color: #2d252a;
}

.writer-placeholder {
	color: #c6b5bd;
}

.body-foot {
	height: 160rpx;
}

.fixed-footer {
	position: fixed;
	left: 0;
	right: 0;
	bottom: 0;
	z-index: 25;
	padding: 16rpx 24rpx calc(16rpx + env(safe-area-inset-bottom));
	background: rgba(255, 255, 255, 0.96);
	box-shadow: 0 -8rpx 24rpx rgba(31, 31, 38, 0.04);
	backdrop-filter: blur(14rpx);
}

.save-btn {
	height: 84rpx;
	border-radius: 999rpx;
	display: flex;
	align-items: center;
	justify-content: center;
	background: linear-gradient(135deg, #e1a8bb 0%, #ca889f 100%);
	color: #ffffff;
	font-size: 28rpx;
	font-weight: 700;
	box-shadow: 0 10rpx 24rpx rgba(202, 136, 159, 0.24);
}

.save-btn.is-disabled {
	opacity: 0.45;
}
</style>
